<?php require_once __DIR__.'/lib.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM contracts WHERE id=?');$s->execute([$id]);$c=$s->fetch();if(!$c||!$c['final_pdf'])die('파일 없음');$ok=false;session_start();if(!empty($_SESSION['admin']))$ok=true;$key=(string)($_GET['key']??'');$expected=hash_hmac('sha256',(string)$id.'|'.$c['document_hash'],(string)cfg('security.app_key'));if($key&&hash_equals($expected,$key))$ok=true;if(!$ok){http_response_code(403);die('다운로드 권한이 없습니다.');}$f=__DIR__.'/'.$c['final_pdf'];if(!is_file($f))die('파일 없음');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="lease_contract_'.$id.'.pdf"');header('Content-Length: '.filesize($f));readfile($f);